insert into public.exercises (id, user_id, slug, name, kind, default_target, cues, progression, is_pair, form_video_url, demo_variants) values
  ('e1000000-0000-4000-8000-000000000001', null, 'incline-push-up', 'Incline push-up', 'max_reps', null, array['Hands on a table, wider than shoulders.', 'Head to heels in one line.', 'Lower for 2 seconds, press for 1.']::text[], 'At 15 clean reps, move your hands lower: chair seat, then floor on knees, then full push-ups.', false, 'https://www.youtube.com/results?search_query=incline%20push%20up%20proper%20form', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000002', null, 'squat', 'Squat', 'reps', 15, array['Feet shoulder-width, toes slightly out.', 'Sit back, chest up.', 'Push through the whole foot.']::text[], 'Add 5 reps when 15 feels easy. Then slow the lowering to 3 seconds, then pause at the bottom.', false, 'https://www.youtube.com/results?search_query=bodyweight%20squat%20proper%20form', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000003', null, 'reverse-lunge', 'Reverse lunge', 'reps_per_side', 10, array['Long step back, lower straight down.', 'Front heel planted.', 'Hold a wall if needed.']::text[], 'Let go of the wall, then add a knee drive at the top.', false, 'https://www.youtube.com/results?search_query=reverse%20lunge%20proper%20form', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000004', null, 'glute-bridge', 'Glute bridge', 'reps', 15, array['Heels close to hips.', 'Squeeze and hold 2 seconds at the top.', 'Do not arch the back.']::text[], 'Add 5 reps when 15 feels easy, then single-leg bridges, 3 × 10 per leg.', false, 'https://www.youtube.com/results?search_query=glute%20bridge%20proper%20form', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000005', null, 'plank', 'Plank', 'timed', 20, array['Elbows under shoulders.', 'Squeeze glutes, ribs down.', 'Stop when hips sag.']::text[], '20 seconds in week 1, 5 seconds more each week, up to 40 seconds.', false, 'https://www.youtube.com/results?search_query=forearm%20plank%20proper%20form', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000006', null, 'dead-bug', 'Dead bug', 'reps', 10, array['Lower back pressed down.', 'Opposite arm and leg extend slowly.', 'Breathe out as you extend.']::text[], 'Start with legs only if the back lifts; then opposite arm and leg.', false, 'https://www.youtube.com/results?search_query=dead%20bug%20exercise%20proper%20form', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000007', null, 'bird-dog', 'Bird dog', 'reps_per_side', 10, array['Hands under shoulders, knees under hips.', 'Reach opposite arm and leg long.', 'Keep hips level.']::text[], 'Add a 2-second hold at full extension.', false, 'https://www.youtube.com/results?search_query=bird%20dog%20exercise%20proper%20form', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000008', null, 'wall-sit', 'Wall sit', 'timed', 30, array['Back flat on the wall.', 'Knees over ankles, thighs level.', 'Breathe steadily.']::text[], 'Add 10 seconds when the full hold feels easy.', false, 'https://www.youtube.com/results?search_query=wall%20sit%20proper%20form', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000009', null, 'calf-raise', 'Calf raise', 'reps', 15, array['Rise high onto the balls of the feet.', 'Pause at the top.', 'Lower slowly.']::text[], 'Add 5 reps, then single-leg raises holding a wall.', false, 'https://www.youtube.com/results?search_query=calf%20raise%20proper%20form', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000021', null, 'mirror-squats', 'Mirror squats', 'reps', 15, array['Face each other.', 'Squat in time, same depth.', 'Chests up, push through the whole foot.']::text[], 'Add 5 reps when 15 feels easy, then slow the lowering together.', true, 'https://www.youtube.com/results?search_query=partner%20squat%20workout', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000022', null, 'hand-hold-lunges', 'Hand-hold reverse lunges', 'reps_per_side', 10, array['Hold hands for balance.', 'Step back together.', 'Front heels planted.']::text[], 'Let go of each other’s hands when balance is solid.', true, 'https://www.youtube.com/results?search_query=partner%20lunges%20workout', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000023', null, 'plank-high-fives', 'Plank high-fives', 'reps_per_side', 10, array['High planks facing each other.', 'Alternate high-fives.', 'Keep hips still as you lift a hand.']::text[], 'Move slightly further apart so you reach more.', true, 'https://www.youtube.com/results?search_query=partner%20plank%20high%20five', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000024', null, 'anchored-sit-ups', 'Anchored sit-ups', 'reps', 12, array['One holds the other’s feet.', 'Curl up slowly, lower with control.', 'Swap after each set.']::text[], 'Add 3 reps each when 12 feels easy.', true, 'https://www.youtube.com/results?search_query=partner%20sit%20ups%20feet%20held', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000025', null, 'you-go-i-go-push-ups', 'You-go-I-go push-ups', 'max_reps', null, array['Take turns to a clean max.', 'Each uses a suitable incline.', 'The resting partner counts.']::text[], 'Each moves to a lower surface at 15 clean reps.', true, 'https://www.youtube.com/results?search_query=partner%20push%20up%20workout', '{"female": null, "male": null, "pair": null}'::jsonb),
  ('e1000000-0000-4000-8000-000000000026', null, 'back-to-back-sit', 'Back-to-back sit', 'timed', 30, array['Backs together, arms linked if you like.', 'Lower to a seated position.', 'Hold, pushing evenly into each other.']::text[], 'Add 10 seconds when the hold feels easy.', true, 'https://www.youtube.com/results?search_query=partner%20back%20to%20back%20wall%20sit', '{"female": null, "male": null, "pair": null}'::jsonb)
insert into public.workout_tracks (id, user_id, slug, name, description, sets_per_move, rest_seconds, is_couples) values
  ('e2000000-0000-4000-8000-000000000001', null, 'men', 'Men', 'Six moves, three sets, 60 seconds rest. About 25 to 30 minutes.', 3, 60, false),
  ('e2000000-0000-4000-8000-000000000002', null, 'women', 'Women', 'More lower-body and glute work, an easier upper-body start. About 25 to 30 minutes.', 3, 60, false),
  ('e2000000-0000-4000-8000-000000000003', null, 'couples', 'Couples', 'Two people, one phone. You rest while your partner works, so it stays near 30 minutes.', 3, 60, true)
